523→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
524→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
525→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
526→	var raw map[string]json.RawMessage
527→	if err := json.Unmarshal(data, &raw); err != nil {
528→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
529→	}
530→
531→	messagesRaw, ok := raw["messages"]
532→	if !ok {
533→		return data, nil
534→	}
535→
536→	var messages []json.RawMessage
537→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
538→		return nil, fmt.Errorf("failed to parse messages: %w", err)
539→	}
540→
541→	changed := false
542→	for i, msgRaw := range messages {
543→		var msg map[string]json.RawMessage
544→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
545→			continue
546→		}
547→
548→		contentRaw, hasContent := msg["content"]
549→		if !hasContent || len(contentRaw) == 0 {
550→			continue
551→		}
552→
553→		// Skip if already a string
554→		var strContent string
555→		if json.Unmarshal(contentRaw, &strContent) == nil {
556→			continue
557→		}
558→
559→		// Try to convert array of {"text":"..."} to a plain string
560→		var parts []struct {
561→			Text string `json:"text"`
562→		}
563→		if json.Unmarshal(contentRaw, &parts) != nil {
564→			continue
565→		}
566→
567→		var texts []string
568→		for _, p := range parts {
569→			if p.Text != "" {
570→				texts = append(texts, p.Text)
571→			}
572→		}
573→		joined := strings.Join(texts, "\n")
574→		strBytes, err := json.Marshal(joined)
575→		if err != nil {
576→			continue
577→		}
578→		msg["content"] = strBytes
579→		rewritten, err := json.Marshal(msg)
580→		if err != nil {
581→			continue
582→		}
583→		messages[i] = rewritten
584→		changed = true
585→	}
586→
587→	if !changed {
588→		return data, nil
589→	}
590→
591→	rewrittenMessages, err := json.Marshal(messages)
592→	if err != nil {
593→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
594→	}
595→	raw["messages"] = rewrittenMessages
596→
597→	return json.MarshalIndent(raw, "", "  ")
598→}
